package ru.mytv.launcher;
import android.app.Activity;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;
public class Scenes extends FrameLayout {
 final Handler ui=new Handler(Looper.getMainLooper());final Random random=new Random();final ImageView photo;final TextView clock,credit,tip,state;final LinearLayout feedback;final ProgressBar progress;final TextView retry;final boolean onlyClock,overlay,labels,preview;final int photoSeconds,moveSeconds,imageAlpha;volatile boolean running;volatile int generation;boolean showingPhoto,loading;ExecutorService pool;PhotoCatalog catalog;
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView v=new TextView(getContext());v.setText(s);v.setTextSize(size);v.setTextColor(0xffe4ecf9);return v;}
 GradientDrawable box(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(16));return d;}
 public Scenes(Context c,boolean clocks){this(c,clocks,true);}
 public Scenes(Context c,boolean clocks,boolean respectMode){super(c);preview=!respectMode;SharedPreferences p=SaverOptions.prefs(c);onlyClock=clocks||(respectMode&&p.getBoolean("clockMode",false));overlay=p.getBoolean("overlay",false);labels=p.getBoolean("captions",true);photoSeconds=Math.max(30,p.getInt("photo",60));moveSeconds=Math.max(5,p.getInt("move",15));int brightness=Math.max(10,Math.min(100,p.getInt("brightness",100)));imageAlpha=255*brightness/100;setBackgroundColor(Color.BLACK);setFocusableInTouchMode(true);
  photo=new ImageView(c);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);addView(photo,new LayoutParams(-1,-1));clock=text("",Math.max(24,Math.min(96,p.getInt("size",56))));int shade=204*brightness/100;clock.setTextColor(Color.rgb(shade,shade,shade));clock.setText(android.text.format.DateFormat.format("HH:mm",new Date()));addView(clock,new LayoutParams(-2,-2));credit=text("",14);int white=255*brightness/100;credit.setTextColor(Color.rgb(white,white,white));credit.setMaxLines(3);credit.setEllipsize(android.text.TextUtils.TruncateAt.END);credit.setPadding(dp(14),dp(8),dp(14),dp(8));credit.setBackground(box(0x99090d18));LayoutParams cp=new LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.LEFT);cp.setMargins(dp(24),0,dp(24),dp(24));addView(credit,cp);credit.setVisibility(GONE);
  feedback=new LinearLayout(c);feedback.setOrientation(1);feedback.setGravity(Gravity.CENTER);feedback.setPadding(dp(24),dp(20),dp(24),dp(20));feedback.setBackground(box(0xf21b293e));state=text("",17);state.setGravity(Gravity.CENTER);feedback.addView(state,new LinearLayout.LayoutParams(-1,-2));progress=new ProgressBar(c);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(32),dp(32));pp.setMargins(0,dp(14),0,dp(14));feedback.addView(progress,pp);LinearLayout buttons=new LinearLayout(c);retry=button("Повторить",()->load());TextView back=button("Назад",()->closePreview());for(TextView b:new TextView[]{retry,back}){LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,dp(44),1);bp.setMargins(dp(5),dp(12),dp(5),0);buttons.addView(b,bp);}feedback.addView(buttons,new LinearLayout.LayoutParams(-1,-2));LayoutParams fp=new LayoutParams(dp(Math.max(240,Math.min(620,getResources().getConfiguration().screenWidthDp-48))),-2,Gravity.CENTER);addView(feedback,fp);feedback.setVisibility(GONE);tip=text("Предпросмотр · Назад — к настройкам",12);tip.setPadding(dp(10),dp(6),dp(10),dp(6));tip.setBackground(box(0x99090d18));LayoutParams tp=new LayoutParams(-2,-2,Gravity.TOP|Gravity.RIGHT);tp.setMargins(dp(24),dp(20),dp(24),0);addView(tip,tp);tip.setVisibility(preview?VISIBLE:GONE);
 }
 TextView button(String label,Runnable action){TextView b=text(label,15);b.setGravity(Gravity.CENTER);b.setFocusable(true);b.setClickable(true);b.setBackground(box(0xff30445f));b.setOnFocusChangeListener((v,f)->{GradientDrawable d=box(f?0xff4b668b:0xff30445f);if(f)d.setStroke(dp(2),0xffdceaff);v.setBackground(d);});b.setOnClickListener(v->action.run());return b;}
 void closePreview(){if(preview&&getContext() instanceof Activity)((Activity)getContext()).finish();}
 void clockVisibility(){clock.setVisibility(onlyClock||showingPhoto&&overlay||!preview&&!showingPhoto?VISIBLE:INVISIBLE);}
 final Runnable time=new Runnable(){public void run(){if(!running)return;clock.setText(android.text.format.DateFormat.format("HH:mm",new Date()));clockVisibility();ui.postDelayed(this,1000);}};
 final Runnable move=new Runnable(){public void run(){if(!running)return;if(getWidth()==0||getHeight()==0||clock.getWidth()==0||clock.getHeight()==0){ui.postDelayed(this,100);return;}int pad=dp(24),maxX=Math.max(0,getWidth()-clock.getWidth()),maxY=Math.max(0,getHeight()-clock.getHeight()-(labels&&!onlyClock?dp(128):0));int minX=Math.min(pad,maxX),minY=Math.min(pad,maxY),spanX=Math.max(0,maxX-2*pad),spanY=Math.max(0,maxY-2*pad);clock.animate().cancel();clock.animate().x(minX+random.nextInt(spanX+1)).y(minY+random.nextInt(spanY+1)).setDuration(1200).start();ui.postDelayed(this,moveSeconds*1000L);}};
 final Runnable next=()->load();
 void start(){if(running)return;generation++;running=true;loading=false;showingPhoto=false;credit.setVisibility(GONE);clock.setAlpha(1f);clockVisibility();pool=Executors.newSingleThreadExecutor();catalog=new PhotoCatalog(getContext());ui.post(time);ui.post(move);requestFocus();if(!onlyClock)load();}
 void stop(){running=false;loading=false;generation++;ui.removeCallbacksAndMessages(null);if(catalog!=null)catalog.close();if(pool!=null)pool.shutdownNow();photo.animate().cancel();clock.animate().cancel();photo.setImageDrawable(null);feedback.setVisibility(GONE);credit.setVisibility(GONE);}
 static String clean(String s){if(s==null)return "";StringBuilder out=new StringBuilder();for(int i=0;i<s.length()&&out.length()<160;i++){char ch=s.charAt(i);if(Character.isISOControl(ch)||Character.isWhitespace(ch)){if(out.length()>0&&out.charAt(out.length()-1)!=' ')out.append(' ');}else out.append(ch);}return out.toString().trim();}
 void load(){if(!running||onlyClock||loading)return;loading=true;ui.removeCallbacks(next);final int token=generation;final PhotoCatalog request=catalog;if(preview){state.setText("Ищу новую фотографию…\nCommons · Openverse\nПри недоступности — резерв Unsplash");progress.setVisibility(VISIBLE);retry.setVisibility(GONE);feedback.setVisibility(VISIBLE);}pool.submit(()->{PhotoCatalog.Image result=null;String error=null;try{result=request.next();}catch(Exception e){error=e.getMessage();if(error==null)error=e.getClass().getSimpleName();}final PhotoCatalog.Image image=result;final String failure=error;ui.post(()->{if(!running||token!=generation){if(image!=null)image.bitmap.recycle();return;}loading=false;photo.animate().cancel();if(image==null){AppInfo.log(getContext(),"Ошибка источников заставки: "+failure);if(preview){state.setText("Новая фотография не загрузилась\n"+failure);progress.setVisibility(GONE);retry.setVisibility(VISIBLE);feedback.setVisibility(VISIBLE);retry.requestFocus();}else{clockVisibility();ui.postDelayed(next,60000);}return;}feedback.setVisibility(GONE);requestFocus();photo.setImageBitmap(image.bitmap);photo.setImageAlpha(imageAlpha);photo.setAlpha(0f);credit.setVisibility(GONE);credit.setText(image.item.caption());photo.animate().alpha(1f).setDuration(700).withEndAction(()->{if(running&&token==generation){showingPhoto=true;clockVisibility();credit.setVisibility(labels?VISIBLE:GONE);request.shown(image);AppInfo.log(getContext(),"Заставка: "+image.item.source+" · "+image.item.title+" · "+image.item.license+" · "+image.item.page);ui.postDelayed(next,photoSeconds*1000L);}}).start();});});}
}
